// Keeps the page available offline. Generated by build.js (VERSION changes on every build so updates install).
const VERSION = '__VERSION__';
const FILES = ['./', 'index.html', 'skeek-ceremony.html', 'manifest.webmanifest', 'app-icon.png'];
self.addEventListener('install', e => {
  e.waitUntil(caches.open(VERSION).then(c => c.addAll(FILES.map(f => new Request(f, { cache: 'reload' })))).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k !== VERSION).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
// Saved copy first (instant, works offline); the network is only used for anything not saved.
self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET') return;
  e.respondWith(caches.open(VERSION).then(async c => {
    const hit = await c.match(e.request, { ignoreSearch: true }) || (e.request.mode === 'navigate' && await c.match('./'));
    return hit || fetch(e.request);
  }));
});
